-- Run after the schema generated by drizzle-kit.
-- The application role must not own tables and must not have BYPASSRLS.

DO $$
DECLARE
  table_name text;
  tenant_tables text[] := ARRAY[
    'memberships', 'usage_ledger', 'processed_jobs', 'prospect_requests', 'organizations',
    'contacts', 'templates', 'template_versions', 'campaigns',
    'sequence_steps', 'enrollments', 'sends', 'suppressions',
    'inbox_events', 'meetings', 'deals', 'attributions'
  ];
BEGIN
  FOREACH table_name IN ARRAY tenant_tables LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', table_name);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', table_name);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING (tenant_id = current_setting(''app.tenant_id'', true)::uuid) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true)::uuid)',
      table_name
    );
  END LOOP;
END $$;

-- Connections and audit events may contain platform-level rows. Normal tenant
-- requests only see their tenant; platform operations use a separate audited role.
ALTER TABLE connections ENABLE ROW LEVEL SECURITY;
ALTER TABLE connections FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_connections ON connections
  USING (tenant_id = current_setting('app.tenant_id', true)::uuid)
  WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::uuid);

ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_audit ON audit_events
  USING (tenant_id = current_setting('app.tenant_id', true)::uuid)
  WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::uuid);

REVOKE UPDATE, DELETE ON audit_events FROM PUBLIC;
